SET NOCOUNT ON;
SELECT DB_NAME() AS db, (SELECT COUNT(*) FROM yj_field WHERE panel_code IN ('PU_REQ','OTHER_IN','OTHER_IN_DETAIL','OTHER_IN_STATS','OTHER_OUT','OTHER_OUT_DETAIL','OTHER_OUT_STATS','OUTSOURCE_IN','OUTSOURCE_IN_DETAIL','OUTSOURCE_IN_STATS','OUTSOURCE_ISSUE','OUTSOURCE_ISSUE_DETAIL','OUTSOURCE_ISSUE_STATS')) AS 十三面板字段行,
       (SELECT COUNT(*) FROM yj_role_panel WHERE panel_code IN ('PU_REQ','OTHER_IN','OTHER_IN_DETAIL','OTHER_IN_STATS','OTHER_OUT','OTHER_OUT_DETAIL','OTHER_OUT_STATS','OUTSOURCE_IN','OUTSOURCE_IN_DETAIL','OUTSOURCE_IN_STATS','OUTSOURCE_ISSUE','OUTSOURCE_ISSUE_DETAIL','OUTSOURCE_ISSUE_STATS')) AS 授权行;
